C 
C COUNTRY = NAME OF COUNTRY READ IN FROM countrystats.dat
C GRIDNAM = NAME OF GRID WHEN READ IN FROM countrystats.dat
C GRIDUSE = NAME OF GRID REGION SIMULATED FOR PRESENT SIMULATION (SET HERE)
C     
      CHARACTER(11) PATHHOME
      CHARACTER(11) PATHTEMP 
      CHARACTER(11) PATHLOAD
      CHARACTER(20) PTH2LOAD
      CHARACTER(14) FACREGION
      CHARACTER(14) GRIDARG
      CHARACTER(1)  IFARG
      CHARACTER(1)  DCARG
      CHARACTER(14) COUNTRY, NAMEGRID, GRIDNAM,  NAMCOUNGR, GRIDUSE,
     1              NAMECOUN,DOMAIN,   NAMEREAD, DUMMY,     GRIDLOAD,
     1              GRIDCOUN,NAMHTREG, NH,       NAMEORIG,  NAMORIGGR,
     1              NAMELOAD,LOADNAME 
C
C HDDMON = HEATING DEGREE DAYS PER MONTH (F) CONUS AVERAGE 1949-2011 
C        = DEVIATIONS BELOW MEAN DAILY TEMPERATURE OF 65 F SUMMED OVER 
C          ALL DAYS IN MONTH. THIS IS AVERAGE 1949-2011 CONUS   
C          TABLE 1.7 EIA  http://www.eia.gov/totalenergy/data/annual/pdf/aer.pdf
C
        DATA HDDMON / 917., 732., 593., 345., 159.,  39., 
     1                  9.,  15.,  77., 282., 539., 817. /  
C
C CDDMON = COOLING DEGREE DAYS PER MONTH (F) CONUS AVERAGE 1949-2011 
C        = DEVIATIONS ABOVE MEAN DAILY TEMPERATURE OF 65 F SUMMED OVER 
C          ALL DAYS IN MONTH. THIS IS AVERAGE 1949-2011 CONUS   
C          TABLE 1.8 EIA  http://www.eia.gov/totalenergy/data/annual/pdf/aer.pdf
C
        DATA CDDMON /   9.,   8.,  18.,  30.,  97.,  213., 
     1                321., 290., 155.,  53.,  15.,    7. /
C
C VEHPROF = PERCENT OF DAILY VEHICLE CHARGING OCCURRING EACH HOUR OF
C           DAY. HOUR 1 = 0-1AM LOCAL TIME. VALUES MUST ADD TO 100.
C
C 60% OF CHARGING BETWEEN 11 PM - 7 AM
C
C       DATA VEHPROF / 7.5, 7.5, 7.5, 7.5, 7.5, 7.5, 7.5, 2.5, 
C    1                 2.5, 2.5, 2.5, 2.5, 2.5, 2.5, 2.5, 2.5, 
C    1                 2.5, 2.5, 2.5, 2.5, 2.5, 2.5, 2.5, 7.5 / 
C
C 60% OF CHARGIING BETWEEN 8 AM - 4 PM
C
C       DATA VEHPROF / 2.5, 2.5, 2.5, 2.5, 2.5, 2.5, 2.5, 2.5, 
C    1                 7.5, 7.5, 7.5, 7.5, 7.5, 7.5, 7.5, 7.5, 
C    1                 2.5, 2.5, 2.5, 2.5, 2.5, 2.5, 2.5, 2.5 / 
C
C EQUAL CHARGING ALL HOURS OF DAY
C
        DATA VEHPROF / 24*4.1666666666666667 /  
C    
C CAP2022LO = 2019 LOW CAPITAL COST OF ENERGY SOURCES ($MIL/MW-INSTALLED)
C             FROM 50-STATE 50-state-WWS.xlsx 'Cost of Delivered Electricity' TAB
C             ONWIND OFFWIND RESPV COMPV UTILPV CSPSTOR CSPNOSTOR GEOELEC 
C             HYDRO  TIDAL   WAVE  SOLTHERM GEOHEAT EGS 
C             CSPNOST HAS MEAN OF $2.42 (2.07-2.79) MIL/MW SUBTRACTED TO REMOVE
C             STORAGE COST. ASSUME SOLAR THERMAL SAME AS UTILITY PV
C             THUS CAP2022LO(ICSPNOST) = 6.000 - 2.07 = 3.93 $MIL/MW
C             CAP COST SOLAR THERMAL ASSUMES $3600-4000 PER 3.716 M^2 COLLECTOR
C             & 0.7 KW-TH/M2 FOR CUR COST; +SAME SCALING AS UTIL PV FOR 2050 COST
C CAP2022HI = 2019 HI CAPITAL COST OF ENERGY SOURCES ($MIL/MW-INSTALLED) 
C             FROM 50-STATE 50-state-WWS.xlsx 'Cost of Delivered Electricity' TAB
C             ONWIND OFFWIND RESPV COMPV UTILPV CSPSTOR CSPNOSTOR GEOELEC 
C             HYDRO  TIDAL   WAVE  SOLTHERM GEOHEAT EGS 
C             CAP COST SOLAR THERMAL ASSUMES $3600-4000 PER 3.716 M^2 COLLECTOR
C             & 0.7 KW-TH/M2 FOR CUR COST; +SAME SCALING AS UTIL PV FOR 2050 COST
C CAP2050LO = 2050 LOW CAPITAL COST OF ENERGY SOURCES ($MIL/MW-INSTALLED) 
C             FROM 50-STATE 50-state-WWS.xlsx 'Cost of Delivered Electricity' TAB
C             ONWIND OFFWIND RESPV COMPV UTILPV CSPSTOR CSPNOSTOR GEOELEC 
C             HYDRO  TIDAL   WAVE  SOLTHERM GEOHEAT EGS 
C             CAP COST SOLAR THERMAL ASSUMES $3600-4000 PER 3.716 M^2 COLLECTOR
C             & 0.7 KW-TH/M2 FOR CUR COST; +SAME SCALING AS UTIL PV FOR 2050 COST
C CAP2050HI = 2050 HI CAPITAL COST OF ENERGY SOURCES ($MIL/MW-INSTALLED) 
C             FROM 50-STATE 50-state-WWS.xlsx 'Cost of Delivered Electricity' TAB
C             ONWIND OFFWIND RESPV COMPV UTILPV CSPSTOR CSPNOSTOR GEOELEC 
C             HYDRO  TIDAL   WAVE  SOLTHERM GEOHEAT EGS 
C             CAP COST SOLAR THERMAL ASSUMES $3600-4000 PER 3.716 M^2 COLLECTOR
C             & 0.7 KW-TH/M2 FOR CUR COST; +SAME SCALING AS UTIL PV FOR 2050 COST
C
C CSP IS GIVEN WITH AND WITHOUT STORAGE SINCE 50-STATES-WWS-xlsx ASSUMES STORAGE.
C THE ADDITIONAL COST OF STORAGE IS FOR ADDITIONAL MIRRORS TO OVERSIZE
C GENERATION OF HEAT RELATIVE TO RATED POWER OF TURBINE BY A FACTOR OF 3.2.
C COST OF PHASE-CHANGE MATERIAL FOR STORAGE IS INCLUDED.
C
C CAP2022LO(ICSPSTOR) IS NOT USED HERE SINCE STORAGE COST IS CALCULATED
C SEPARATE (COSTSTORL, COSTSTORM, COSTSTORH)
C
C         ONWIND OFFWIND RESPV COMPV UTILPV CSPSTOR CSPNOSTOR GEOELEC 
C         HYDRO  TIDAL   WAVE  SOLTHERM GEOHEAT EGS  
C
C GEOTHERMAL: EGS+CONVENTIONAL FROM  https://atb.nrel.gov/electricity/2023/geothermal
C             CONVEN (HYDRO) BINARY: 2022:  $9,274/KW; 2035:  $7,188/KW; 2050:  $6,668/KW
C             NEAR-FIELD EGS BINARY: 2022: $29,117/KW; 2035: $10,066/KW; 2050:  $9,337/KW 
C             DEEP EGS BINARY:       2022: $41,652/KW; 2035: $13,069/KW; 2050: $12,122/KW 
C             DEEP EGS BINARY:       2025:  $7,000/KW;                   2050: $ 3,000/KW 
C             https://www.eenews.net/articles/a-6-5b-geothermal-company-industry-eyes-tipping-point/
C FERVO SAYS $85/MWH BY 2028 --> SCALE NREL RESULTS TO GET $6,200/KW in 2028.
C 2022 LOW, HIGH CAPITAL COST IN 2020 USD FROM 'Cost of delivered electricity' TAB
C 145Countries.xlsx
C
C TEST LO, MED, HI CAPITAL COSTS OF EGS
C
C FOR 150 COUNTRIES 2022
      DATA CAP2022LO
     1    /1.025,2.50, 2.23, 1.20, 0.775, 6.00, 3.50, 4.05,
     1     2.40, 4.50, 4.50, 1.30, 4.05,  5.00/
      DATA CAP2022HI
     1    /1.45, 4.00, 2.825,2.16, 1.060, 9.09, 4.00, 6.05,
     1     3.20, 6.50, 8.00, 1.50, 6.05,  9.00/
C
C 2050 LOW, HIGH CAPITAL COST IN 2020 USD FROM 'Cost of delivered electricity' TAB
C 145Countries.xlsx
C
C FOR 150 COUNTRIES 2050
      DATA CAP2050LO
     1    /0.648, 1.236, 0.897, 0.538, 0.383, 2.138, 1.247, 3.885,
     1     2.332, 1.397, 1.190, 0.822, 3.885, 2.5/
      DATA CAP2050HI
