     1       'DECOMMISS % CAP COST      (%/YR)  LO MN HI= ',3(0PF12.5)/,
     1       'CAP COST ELEC GENERATORS  ($TRIL) LO MN HI= ',3(0PF12.5)/,
     1       'CAP COST HEAT GENERATORS  ($TRIL) LO MN HI= ',3(0PF12.5)/,
