     1       'CAP COST H2 ELEC STORAGE  ($TRIL) LO MN HI= ',3(0PF12.5)/,
     1       'CAP COST CSPPCM+PHS STOR  ($TRIL) LO MN HI= ',3(0PF12.5)/,
