     1       'ONSHORE WIND                 = ',1(0PF13.5)/,
     1       'OFFSHORE WIND                = ',1(0PF13.5)/,
     1       'ROOFTOP PV                   = ',1(0PF13.5)/,
     1       'UTILITY PV                   = ',1(0PF13.5)/,
     1       'CSP (INCLUDING FROM STORAGE) = ',1(0PF13.5)/,
     1       'HYDROELECTRIC                = ',1(0PF13.5)/,
     1       'WAVE                         = ',1(0PF13.5)/,
     1       'CONVENTIONAL GEOTHERMAL ELEC = ',1(0PF13.5)/,
     1       'EGS GEOTHERMAL ELEC          = ',1(0PF13.5)/,
     1       'TIDAL                        = ',1(0PF13.5)/,
     1       'SOLAR THERMAL                = ',1(0PF13.5)/, 
     1       'GEOTHERMAL HEAT              = ',1(0PF13.5)/)
 289  FORMAT('TWH TSUMCSTLS TREMCSTOR   FINEFFIC     ',
     1       'EFFCSP       CFCSP',/,5(0PF13.5))
 292  FORMAT('TWH TSUMPSTLS TREMPSTOR   FINEFFIC     ',
     1       'EFFPHS       CFPHS  ',/,5(0PF13.5))
 597  FORMAT('TWH    --     TWHHYD       --          ',
